public void manualControl(double power) {
    if (!isAvailable() || !armed) return;
    mode = ClimberMode.MANUAL;
    manualPower = DriverInput.clamp(power * MANUAL_POWER_LIMIT, -1.0, 1.0);  // stores only
}

private double limitPowerAtTravelEnds(double power, double currentAngle) {
    if (power > 0 && currentAngle >= MAX_ANGLE_DEGREES) return 0;
    if (power < 0 && currentAngle <= MIN_ANGLE_DEGREES) return 0;
    return power;   // blocking BOTH directions would trap the mechanism at its limit
}

